{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2190-12-13 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. I'm Dr. Lee, one of your cardiac surgeons. You're here because your heart failure has been getting worse, and we need to fix your severely leaking mitral valve and blocked heart arteries."
    },
    {
      "turn_number": 2,
      "time": "2190-12-13 08:02:00",
      "speaker": "Patient",
      "text": "Yes, I’ve been so short of breath lately, even just walking to the bathroom. My legs are swollen too."
    },
    {
      "turn_number": 3,
      "time": "2190-12-13 08:03:00",
      "speaker": "Doctor",
      "text": "I see that. Your echocardiograms show your mitral valve is leaking badly, and it’s because of poor blood flow to that part of the heart. We confirmed that with a stress test showing a problem in the back wall."
    },
    {
      "turn_number": 4,
      "time": "2190-12-13 08:05:00",
      "speaker": "Patient",
      "text": "So what’s the plan? I remember last time they didn’t do the cath because of my kidneys."
    },
    {
      "turn_number": 5,
      "time": "2190-12-13 08:06:00",
      "speaker": "Doctor",
      "text": "Exactly. This time, we’re admitting you early so we can hydrate you well and protect your kidneys. But based on your history and symptoms, we’ve decided to go straight to surgery."
    },
    {
      "turn_number": 6,
      "time": "2190-12-13 08:08:00",
      "speaker": "Patient",
      "text": "Surgery? What kind?"
    },
    {
      "turn_number": 7,
      "time": "2190-12-13 08:09:00",
      "speaker": "Doctor",
      "text": "We’ll do two things: first, a triple bypass to improve blood flow to your heart. Then, we’ll replace your mitral valve with a mechanical one."
    },
    {
      "turn_number": 8,
      "time": "2190-12-13 08:11:00",
      "speaker": "Patient",
      "text": "Mechanical? That means I’ll need blood thinners?"
    },
    {
      "turn_number": 9,
      "time": "2190-12-13 08:12:00",
      "speaker": "Doctor",
      "text": "Yes, exactly. You’ll be on warfarin for life, with a target INR between 2.5 and 3.5. We’ll start that soon after surgery."
    },
    {
      "turn_number": 10,
      "time": "2190-12-13 08:14:00",
      "speaker": "Patient",
      "text": "And my kidney? I’m worried about that. I’m already on my second transplant."
    },
    {
      "turn_number": 11,
      "time": "2190-12-13 08:15:00",
      "speaker": "Doctor",
      "text": "Transplant medicine is following you closely. Your creatinine is elevated at 3.5, but stable. We’re monitoring it daily and avoiding anything that could hurt your kidneys."
    },
    {
      "turn_number": 12,
      "time": "2190-12-13 08:17:00",
      "speaker": "Patient",
      "text": "Okay, that helps. When is the surgery?"
    },
    {
      "turn_number": 13,
      "time": "2190-12-13 08:18:00",
      "speaker": "Doctor",
      "text": "Today. You’ll go to the OR in a few hours. We’ll use your left leg vein for two of the bypasses and the internal mammary artery for the third."
    },
    {
      "turn_number": 14,
      "time": "2190-12-13 08:20:00",
      "speaker": "Patient",
      "text": "My leg? Will that be okay?"
    },
    {
      "turn_number": 15,
      "time": "2190-12-13 08:21:00",
      "speaker": "Doctor",
      "text": "We’ll harvest the vein endoscopically, so small incisions. There might be some swelling or drainage, but we’ll watch it."
    },
    {
      "turn_number": 16,
      "time": "2190-12-13 12:00:00",
      "speaker": "Doctor",
      "text": "The surgery is complete. You had a triple bypass and a mechanical mitral valve replacement. You tolerated it well."
    },
    {
      "turn_number": 17,
      "time": "2190-12-14 07:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’re in the CVICU. You were extubated this morning. How are you feeling?"
    },
    {
      "turn_number": 18,
      "time": "2190-12-14 07:02:00",
      "speaker": "Patient",
      "text": "Tired. My chest hurts, and I can’t catch my breath well."
    },
    {
      "turn_number": 19,
      "time": "2190-12-14 07:04:00",
      "speaker": "Doctor",
      "text": "That’s expected. Your heart function was already reduced—your ejection fraction is about 35%. We’re supporting you with medications, but it will take time."
    },
    {
      "turn_number": 20,
      "time": "2190-12-14 07:06:00",
      "speaker": "Patient",
      "text": "Is my new valve working?"
    },
    {
      "turn_number": 21,
      "time": "2190-12-14 07:07:00",
      "speaker": "Doctor",
      "text": "Yes. The intra-op echo showed the mechanical valve is functioning well with normal gradients. No leaks."
    },
    {
      "turn_number": 22,
      "time": "2190-12-14 07:09:00",
      "speaker": "Patient",
      "text": "And my kidneys?"
    },
    {
      "turn_number": 23,
      "time": "2190-12-14 07:10:00",
      "speaker": "Doctor",
      "text": "Creatinine is 3.4 today—stable. No dialysis needed. We’re keeping you hydrated and avoiding nephrotoxins."
    },
    {
      "turn_number": 24,
      "time": "2190-12-14 07:12:00",
      "speaker": "Patient",
      "text": "Good. What about the blood thinner?"
    },
    {
      "turn_number": 25,
      "time": "2190-12-14 07:13:00",
      "speaker": "Doctor",
      "text": "We’ve started warfarin. We’ll check your INR daily and adjust the dose to keep it in the safe range."
    },
    {
      "turn_number": 26,
      "time": "2190-12-15 08:00:00",
      "speaker": "Doctor",
      "text": "Your chest X-ray shows mild fluid in the lungs, which is common after heart surgery. We’ll keep an eye on it."
    },
    {
      "turn_number": 27,
      "time": "2190-12-15 08:02:00",
      "speaker": "Patient",
      "text": "I feel a bit more short of breath today."
    },
    {
      "turn_number": 28,
      "time": "2190-12-15 08:04:00",
      "speaker": "Doctor",
      "text": "Yes, the X-ray shows a small right pleural effusion and mild edema. We’ll adjust your fluids and continue diuresis gently."
    },
    {
      "turn_number": 29,
      "time": "2190-12-15 08:06:00",
      "speaker": "Patient",
      "text": "Will that go away?"
    },
    {
      "turn_number": 30,
      "time": "2190-12-15 08:07:00",
      "speaker": "Doctor",
      "text": "Yes, as your heart recovers and we manage fluid balance. Your heart is still weak, so we have to be careful."
    },
    {
      "turn_number": 31,
      "time": "2190-12-16 07:30:00",
      "speaker": "Doctor",
      "text": "Great news—you’re moving to the telemetry floor today. Your vitals are stable, and you’re off all IV medications."
    },
    {
      "turn_number": 32,
      "time": "2190-12-16 07:32:00",
      "speaker": "Patient",
      "text": "That’s a relief. Can I start walking?"
    },
    {
      "turn_number": 33,
      "time": "2190-12-16 07:34:00",
      "speaker": "Doctor",
      "text": "Yes, physical therapy will help you today. It’s important to rebuild strength, but go slow."
    },
    {
      "turn_number": 34,
      "time": "2190-12-16 07:36:00",
      "speaker": "Patient",
      "text": "My leg incision is oozing a bit."
    },
    {
      "turn_number": 35,
      "time": "2190-12-16 07:37:00",
      "speaker": "Doctor",
      "text": "Yes, the vein harvest site dehisced during surgery but was closed with staples. There’s some serosanguinous drainage—normal for now. We’ll keep it clean."
    },
    {
      "turn_number": 36,
      "time": "2190-12-17 08:00:00",
      "speaker": "Doctor",
      "text": "Your INR is 2.6 today—perfect. We’ll keep you on 1 mg warfarin daily."
    },
    {
      "turn_number": 37,
      "time": "2190-12-17 08:02:00",
      "speaker": "Patient",
      "text": "Good. And my other meds?"
    },
    {
      "turn_number": 38,
      "time": "2190-12-17 08:04:00",
      "speaker": "Doctor",
      "text": "We’ve adjusted them. You’re on lower-dose carvedilol, hydralazine for blood pressure, and we stopped furosemide since you’re not retaining fluid now."
    },
    {
      "turn_number": 39,
      "time": "2190-12-17 08:06:00",
      "speaker": "Patient",
      "text": "What about my transplant meds?"
    },
    {
      "turn_number": 40,
      "time": "2190-12-17 08:07:00",
      "speaker": "Doctor",
      "text": "Tacrolimus and sirolimus are continuing. Levels are therapeutic. Transplant team will follow you after discharge."
    },
    {
      "turn_number": 41,
      "time": "2190-12-18 07:30:00",
      "speaker": "Doctor",
      "text": "You’re doing well. We’ll remove your pacing wires today—they’re no longer needed."
    },
    {
      "turn_number": 42,
      "time": "2190-12-18 07:32:00",
      "speaker": "Patient",
      "text": "Any pain with that?"
    },
    {
      "turn_number": 43,
      "time": "2190-12-18 07:33:00",
      "speaker": "Doctor",
      "text": "Just a quick pinch. We’ll give you some tramadol beforehand."
    },
    {
      "turn_number": 44,
      "time": "2190-12-18 07:45:00",
      "speaker": "Doctor",
      "text": "All done. No issues. You’re healing well."
    },
    {
      "turn_number": 45,
      "time": "2190-12-19 09:00:00",
      "speaker": "Doctor",
      "text": "Today’s the day. You’re being discharged to an extended care facility for rehab."
    },
    {
      "turn_number": 46,
      "time": "2190-12-19 09:02:00",
      "speaker": "Patient",
      "text": "I’m ready. What do I need to do at home later?"
    },
    {
      "turn_number": 47,
      "time": "2190-12-19 09:04:00",
      "speaker": "Doctor",
      "text": "Shower daily, but no baths. Wash incisions gently. No lifting over 10 pounds for 10 weeks. No driving for a month."
    },
    {
      "turn_number": 48,
      "time": "2190-12-19 09:06:00",
      "speaker": "Patient",
      "text": "And my meds?"
    },
    {
      "turn_number": 49,
      "time": "2190-12-19 09:07:00",
      "speaker": "Doctor",
      "text": "You’ll take warfarin, aspirin, transplant meds, insulin, and others as listed. We’ll monitor INR closely at follow-up."
    },
    {
      "turn_number": 50,
      "time": "2190-12-19 09:09:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor. I feel hopeful."
    },
    {
      "turn_number": 51,
      "time": "2190-12-19 09:10:00",
      "speaker": "Doctor",
      "text": "You’ve been through a lot, but you’re on the right path. Call us with any concerns. You’ll see the surgeon in two weeks."
    },
    {
      "turn_number": 52,
      "time": "2190-12-19 09:12:00",
      "speaker": "Patient",
      "text": "I will. And thank you for taking care of my heart."
    },
    {
      "turn_number": 53,
      "time": "2190-12-19 09:13:00",
      "speaker": "Doctor",
      "text": "That’s our job. Take it one day at a time. You’re going to do well."
    },
    {
      "turn_number": 54,
      "time": "2190-12-19 09:15:00",
      "speaker": "Patient",
      "text": "I’ll try. It’s just a lot to manage—heart, kidneys, diabetes, transplants."
    },
    {
      "turn_number": 55,
      "time": "2190-12-19 09:17:00",
      "speaker": "Doctor",
      "text": "It is a lot. But you’re not alone. We have teams for each part. You’re strong—you’ve been through two transplants already."
    },
    {
      "turn_number": 56,
      "time": "2190-12-19 09:19:00",
      "speaker": "Patient",
      "text": "That’s true. I’ve made it this far."
    },
    {
      "turn_number": 57,
      "time": "2190-12-19 09:20:00",
      "speaker": "Doctor",
      "text": "And you’ll keep going. Rehab will help you regain strength. Focus on healing first."
    },
    {
      "turn_number": 58,
      "time": "2190-12-19 09:22:00",
      "speaker": "Patient",
      "text": "I’ll do my best."
    },
    {
      "turn_number": 59,
      "time": "2190-12-19 09:23:00",
      "speaker": "Doctor",
      "text": "That’s all we ask. We’ll see you soon in clinic."
    },
    {
      "turn_number": 60,
      "time": "2190-12-19 09:25:00",
      "speaker": "Patient",
      "text": "Thank you again."
    },
    {
      "turn_number": 61,
      "time": "2190-12-19 09:26:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care."
    },
    {
      "turn_number": 62,
      "time": "2190-12-19 09:28:00",
      "speaker": "Patient",
      "text": "One last thing—should I worry about infection?"
    },
    {
      "turn_number": 63,
      "time": "2190-12-19 09:29:00",
      "speaker": "Doctor",
      "text": "Good question. We screened for MRSA—negative. Your urine culture was clean. Keep incisions dry and watch for redness, fever, or increased drainage."
    },
    {
      "turn_number": 64,
      "time": "2190-12-19 09:31:00",
      "speaker": "Patient",
      "text": "I will. And I’ll check my temperature every night."
    },
    {
      "turn_number": 65,
      "time": "2190-12-19 09:32:00",
      "speaker": "Doctor",
      "text": "Exactly. And weigh yourself each morning. Call if you gain more than 2 pounds in a day."
    },
    {
      "turn_number": 66,
      "time": "2190-12-19 09:34:00",
      "speaker": "Patient",
      "text": "Got it. I’ll keep the log."
    },
    {
      "turn_number": 67,
      "time": "2190-12-19 09:35:00",
      "speaker": "Doctor",
      "text": "Perfect. You’re ready."
    }
  ],
  "summary": {
    "admission_start": "2190-12-13 07:30:00",
    "admission_end": "2190-12-19 16:03:00",
    "summary_paragraph": "A 60-year-old female with a history of type I diabetes, end-stage renal disease with prior kidney and pancreas transplants, and severe mitral regurgitation was admitted for worsening heart failure symptoms. She underwent elective coronary artery bypass grafting x3 and mechanical mitral valve replacement. The surgery was performed due to severe three-vessel coronary disease and ischemic mitral regurgitation. She tolerated the procedure well, was extubated on postoperative day one, and transitioned to the telemetry floor. Her renal function remained stable throughout admission, and she was managed on warfarin for mechanical valve anticoagulation. By discharge on postoperative day six, she was ambulating with assistance, pain was controlled with oral medications, and incisions were healing. She was discharged to an extended care facility for rehabilitation with detailed instructions on wound care, activity restrictions, and medication management.",
    "problems": [
      "Mitral valve disorders",
      "Acute kidney failure with lesion of tubular necrosis",
      "Pancreas replaced by transplant",
      "Complications of transplanted kidney",
      "Coronary atherosclerosis of native coronary artery",
      "Other and unspecified hyperlipidemia",
      "Unspecified essential hypertension",
      "Peripheral vascular disease, unspecified",
      "Surgical operation with transplant of whole organ causing abnormal patient reaction, or later complication, without mention of misadventure at time of operation"
    ]
  }
}
